        /// <summary>
        /// Every harmful ApplyStatus on `unit` whose authored chance is exactly 1.0, plus any of
        /// them that stops resolving to 1.0 against some enemy's Effect Resist. Known trap 4: the
        /// float `1f + hit - resist` is 0.99999994 when hit equals resist, which turns a certainty
        /// into a draw with nothing in the content file changing.
        ///
        /// A default of 1.0 is indistinguishable from an authored 1.0 in the parsed def, and that
        /// is the point - both are a claim that the status always lands, and both break the same way.
        /// </summary>
        private static void CollectCertainHarmfulStatuses(ContentDatabase db, UnitDef unit,
                                                          List<string> certain, List<string> broken)
        {
            List<AbilityDef> abilities = new List<AbilityDef>();
            if (unit.BasicAttack != null) abilities.Add(unit.BasicAttack);
            if (unit.Active != null) abilities.Add(unit.Active);
            for (int p = 0; p < unit.Passives.Count; p++)
            {
                AbilityDef wrapper = new AbilityDef();
                wrapper.Name = unit.Passives[p].Name;
                wrapper.Effects = unit.Passives[p].Effects;
                abilities.Add(wrapper);
            }

            for (int a = 0; a < abilities.Count; a++)
            {
                for (int e = 0; e < abilities[a].Effects.Count; e++)
                {
                    EffectDef eff = abilities[a].Effects[e];
                    if (eff.Kind != EffectKind.ApplyStatus) continue;
                    if (!StatusInfo.IsHarmful(eff.Status)) continue;
                    if (eff.BypassResist) continue;
                    if (eff.Chance < 1f) continue;

                    string label = unit.Id + "/" + abilities[a].Name + "/" + eff.Status;
                    certain.Add(label);
                    for (int f = 0; f < db.Enemies.Count; f++)
                    {
                        EnemyDef foe = db.Enemies[f];
                        float landing = CombatSimulation.ResolveLandingChance(eff.Chance, eff.Status, unit.EffectHit, foe.EffectResist);
                        if (landing < 1f)
                            broken.Add(label + " rolls against " + foe.Id + " at " + Fmt(landing));
                    }
                }
            }
        }

        /// <summary>Catches authoring mistakes where an effect's numeric fields are all zero, so it silently does nothing.</summary>
        private static void CheckAbilityPotency(ContentDatabase db)
        {
            Line("ABILITY POTENCY");
            bool zeroFound = false;
            List<UnitDef> units = new List<UnitDef>();
            for (int i = 0; i < db.Heroes.Count; i++) units.Add(db.Heroes[i]);
            for (int i = 0; i < db.Enemies.Count; i++) units.Add(db.Enemies[i]);

            for (int u = 0; u < units.Count; u++)
            {
                UnitDef def = units[u];
                if (CheckAbilityEffects(def.BasicAttack, def.Name, "basic")) zeroFound = true;
                if (CheckAbilityEffects(def.Active, def.Name, "active")) zeroFound = true;
                for (int p = 0; p < def.Passives.Count; p++)
                {
                    AbilityDef wrapper = new AbilityDef();
                    wrapper.Name = def.Passives[p].Name;
                    wrapper.Effects = def.Passives[p].Effects;
                    if (CheckAbilityEffects(wrapper, def.Name, "passive")) zeroFound = true;
                }
            }
            Check(!zeroFound, "no ability effect is configured to deal, heal or shield exactly zero");
            Line("");
        }

        private static bool CheckAbilityEffects(AbilityDef ability, string ownerName, string slot)
        {
            if (ability == null) return false;
            bool found = false;
            for (int i = 0; i < ability.Effects.Count; i++)
            {
                EffectDef e = ability.Effects[i];
                bool zero = false;
                // A damage term does not have to be a number on the effect. The band scalers
                // carry the whole payout - a record's gap, or a fraction of its highest value - so
                // an effect using one is deliberately written with power 0 and is not empty.
                if (e.Kind == EffectKind.Damage) zero = e.Power <= 0f && e.Flat <= 0f
                    && e.TargetMaxHpRatio <= 0f && e.TargetCurrentHpRatio <= 0f && e.TargetMissingHpRatio <= 0f
                    && !e.ScaleByBandGap && !e.ScaleByBandHigh;
                else if (e.Kind == EffectKind.Heal || e.Kind == EffectKind.Shield) zero = e.Power <= 0f && e.Flat <= 0f && e.SelfHpRatio <= 0f;
                else if (e.Kind == EffectKind.EnergyGain) zero = e.Power <= 0f && e.Flat == 0f;
                if (zero)
                {
                    found = true;
                    Line("  [FAIL] " + ownerName + "'s " + slot + " ability \"" + ability.Name + "\" has a " + e.Kind + " effect worth zero");
                }
            }
            return found;
        }

        /// <summary>
        /// OnKill passive mechanics, proven in a synthetic arena.
        ///
        /// Part A scans shipped content for OnKill passives and checks that none can themselves
        /// land a kill (recursion safety: DealRawDamage fires OnKill at hardcoded depth 0, so
        /// MaxPassiveDepth does not bound it - the path is kept unreachable by content).
        ///
        /// Part B proves the trigger itself in a synthetic arena: a hero with an OnKill passive
        /// fights fodder, and every PassiveTrigger event must sit directly behind a Death from
        /// the same source.
        /// </summary>
        private static void CheckOnKillPassive(ContentDatabase db)
        {
            Line("ON-KILL PASSIVE");

            // -- Part A: content scan (recursion safety) --
            List<UnitDef> units = new List<UnitDef>();
            for (int i = 0; i < db.Heroes.Count; i++) units.Add(db.Heroes[i]);
            for (int i = 0; i < db.Enemies.Count; i++) units.Add(db.Enemies[i]);

            List<string> onKill = new List<string>();
            List<string> lethal = new List<string>();
            for (int i = 0; i < units.Count; i++)
            {
                for (int k = 0; k < units[i].Passives.Count; k++)
                {
                    PassiveDef p = units[i].Passives[k];
                    if (p == null || p.Trigger != PassiveTrigger.OnKill) continue;
                    onKill.Add(units[i].Id + "/" + p.Name);
                    if (PassiveCanKill(p)) lethal.Add(units[i].Id + "/" + p.Name);
                }
            }

            if (onKill.Count == 0)
                Line("  [note] no shipped content authors OnKill - the recursion-safety scan passes"
                     + " vacuously and the mechanic is unreachable in shipped content until abilities land");
            else
                Check(true, "OnKill is authored in shipped content: " + string.Join(", ", onKill.ToArray()));

            Check(lethal.Count == 0,
                  "no OnKill passive can itself land a kill (" + string.Join(", ", lethal.ToArray())
                  + ") - DealRawDamage fires OnKill at a hardcoded depth 0, so MaxPassiveDepth does not bound it"
                  + " and the recursion is kept unreachable by content rather than by that guard");

            // -- Part B: synthetic arena proves the engine mechanic works --
            ContentDatabase arena = BuildOnKillTestContent();
            if (arena == null) { Line(""); return; }

            GameSession session = new GameSession(arena, GameSession.CreateNewProfile(arena, 0));
            BattleResult r = CombatSimulation.Run(session.BuildBattleRequest(Opening(arena.AllStages[0]), 42));

            int fired = 0, notBehindAKill = 0;
            for (int i = 0; i < r.Events.Count; i++)
            {
                BattleEvent e = r.Events[i];
                if (e.Type != BattleEventType.PassiveTrigger) continue;
                if (e.AbilityId != "killer_onkill") continue;
                fired++;
                BattleEvent prev = i > 0 ? r.Events[i - 1] : null;
                if (prev == null || prev.Type != BattleEventType.Death || prev.SourceId != e.SourceId)
                    notBehindAKill++;
            }

            Check(fired > 0, "OnKill passive fires in a synthetic arena (" + fired + " time(s))");
            Check(notBehindAKill == 0,
                  "every OnKill trigger sat directly behind a Death that the killer caused (" + notBehindAKill
                  + " did not) - it is a kill trigger, not a crit trigger");

            Line("");
        }

