      ""basic"": { ""id"": ""b5xbt_basic"", ""name"": ""Poke"",
        ""effects"": [ { ""kind"": ""Damage"", ""target"": ""FrontEnemy"", ""power"": 0.001 } ] },
      ""active"": { ""id"": ""b5xbt_active"", ""name"": ""Noop"", ""energyCost"": 9999,
