  ]
}";
            string campaign = @"{
  ""chapters"": [ { ""id"": ""bs_ch"", ""name"": ""BlowScalar"", ""stages"": [
    { ""id"": ""bs_arena"", ""index"": 1, ""enemies"": [ { ""id"": ""bs_foe"", ""level"": 1 } ] } ] } ]
