        ""effects"": [ { ""kind"": ""Heal"", ""target"": ""Self"", ""flat"": 1 } ] } },
    { ""id"": ""tc_a"", ""name"": ""TcA"", ""aspect"": ""Ember"", ""role"": ""Striker"",
      ""startingHero"": true,
      ""hp"": 40000, ""attack"": 10, ""defense"": 0, ""speed"": 4, ""critChance"": 0, ""critDamage"": 1.0,
