      ""startEnergy"": 0,
      ""basic"": { ""id"": ""hr_basic"", ""name"": ""Mend"",
        ""effects"": [
          " + reducer + @"
          { ""kind"": ""Damage"", ""target"": ""Self"", ""power"": 3.0 },
